mapper.sql:
/*AdmBulbdBasDAO.listAdmBulbdBas 어드민게시판기본 목록 조회 */ SELECT A.BULBD_ID /* 게시판아이디 */ , A.BULBD_NM /* 게시판명 */ , A.ADM_ATH_YN /* 관리자권한여부 */ , A.MAIN_REPST_YN /* 메인표시여부 */ , A.REPST_ORDR /* 표시순서 */ , A.DESC_CTNT /* 설명내용 */ , A.USE_YN /* 사용여부 */ , A.FRST_REGI_USER_ID /* 최초등록사용자아이디 */ , A.FRST_REGI_TMSP /* 최초등록타임스탬프 */ , A.LAST_CHNG_USER_ID /* 최종변경사용자아이디 */ , A.LAST_CHNG_TMSP /* 최종변경타임스탬프 */ , (SELECT COUNT(BLPS_SEQNO) FROM ADM_BULBD_TXN WHERE BULBD_ID = A.BULBD_ID) AS BLPS_COUNT /*게시건수*/ FROM ADM_BULBD_BAS A
AND ADM_ATH_YN = #{admAthYn}
AND BULBD_NM LIKE CONCAT('%', #{bulbdNm}, '%')

mapper.select:
SELECT COUNT(*) AS totalCount FROM ADM_BULBD_BAS WHERE 1=1
AND ADM_ATH_YN = #{admAthYn}
AND BULBD_NM LIKE CONCAT('%', #{bulbdNm}, '%')
